public class CommandBuilder {
	private final CommandDispatcher<CommandSourceStack> dispatcher;
	private final LiteralArgumentBuilder<CommandSourceStack> root;

	public CommandBuilder(CommandDispatcher<CommandSourceStack> dispatcher, String name) {
		this.dispatcher = dispatcher;
		this.root = LiteralArgumentBuilder.literal(name);
	}

	public CommandBuilder argument(String name, ArgumentType<?> type) {
		var argument = RequiredArgumentBuilder.argument(name, type);
		root.then(argument);
		return this;
	}

	public CommandBuilder requires(Predicate<CommandSourceStack> requirement) {
		root.requires(requirement);
		return this;
	}

	public CommandBuilder permission(int level) {
		return requires(s -> s.hasPermission(level));
	}

	public CommandBuilder executes(CommandExecutor<CommandSourceStack> executor) {
		root.executes(executor);
		return this;
	}

	public CommandBuilder then(ArgumentBuilder<CommandSourceStack, ?> argument) {
		root.then(argument);
		return this;
	}

	public void register() {
		dispatcher.register(root);
	}
}
